UPDATE nginx_referer_stat
SET request_count = request_count + #{requestCount},
    sum_request_time_ms = sum_request_time_ms + #{sumRequestTimeMs},
    max_request_time_ms = CASE WHEN #{maxRequestTimeMs} > max_request_time_ms THEN #{maxRequestTimeMs} ELSE max_request_time_ms END,
    slow_count = slow_count + #{slowCount},
    status_5xx = status_5xx + #{status5xx}
WHERE source_id = #{sourceId}
  AND bucket_time = #{bucketTime}
  AND referer = #{referer}

mapper.insert:
INSERT INTO nginx_referer_stat (
    source_id, bucket_time, referer, request_count,
    sum_request_time_ms, max_request_time_ms, slow_count, status_5xx, create_time
) VALUES (
    #{row.sourceId}, #{row.bucketTime}, #{row.referer}, #{row.requestCount},
    #{row.sumRequestTimeMs}, #{row.maxRequestTimeMs}, #{row.slowCount}, #{row.status5xx}, #{row.createTime}
)

mapper.select:
SELECT user_agent AS "userAgent", SUM(request_count) AS "requestCount", SUM(slow_count) AS "slowCount", SUM(status_5xx) AS "status5xx", MAX(max_request_time_ms) AS "maxRequestTimeMs", ROUND(SUM(sum_request_time_ms) * 1.0 / NULLIF(SUM(request_count), 0), 2) AS "avgRequestTimeMs" FROM nginx_ua_stat WHERE bucket_time >= #{startTime} AND bucket_time < #{endTime} AND source_id IN #{sid}
AND user_agent LIKE '%' || #{keyword} || '%'
GROUP BY user_agent ORDER BY SUM(request_count) DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM (
    SELECT user_agent FROM nginx_ua_stat
    WHERE bucket_time >= #{startTime}
      AND bucket_time < #{endTime}
      AND source_id IN
      #{sid}

          AND user_agent LIKE '%' || #{keyword} || '%'

    GROUP BY user_agent
) t

SELECT referer AS "referer", SUM(request_count) AS "requestCount", SUM(slow_count) AS "slowCount", SUM(status_5xx) AS "status5xx", MAX(max_request_time_ms) AS "maxRequestTimeMs", ROUND(SUM(sum_request_time_ms) * 1.0 / NULLIF(SUM(request_count), 0), 2) AS "avgRequestTimeMs" FROM nginx_referer_stat WHERE bucket_time >= #{startTime} AND bucket_time < #{endTime} AND source_id IN #{sid}
AND referer LIKE '%' || #{keyword} || '%'
GROUP BY referer ORDER BY SUM(request_count) DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM (
    SELECT referer FROM nginx_referer_stat
    WHERE bucket_time >= #{startTime}
      AND bucket_time < #{endTime}
      AND source_id IN
      #{sid}

          AND referer LIKE '%' || #{keyword} || '%'

    GROUP BY referer
) t

SELECT id AS "id", ts AS "ts", client_ip AS "clientIp", uri AS "uri", method AS "method",
       request_time_ms AS "requestTimeMs", upstream_time_ms AS "upstreamTimeMs",
       status AS "status", user_agent AS "userAgent", referer AS "referer"
FROM nginx_request_sample
WHERE ts >= #{startTime}
  AND ts < #{endTime}
  AND source_id IN
  #{sid}
ORDER BY ts DESC
LIMIT #{pageSize} OFFSET #{offset}
